const prompt = $('Classification Prompt').item.json.prompt;
const customerMessage = $json.text;
const fromId = $json.from_id;
const fromUsername = $json.from_username;

const fullPrompt = `${prompt}\n\nCustomer Message:\n${customerMessage}`;

const GEMINI_API_KEY = $env.GEMINI_API_KEY;
const GROQ_API_KEY = $env.GROQ_API_KEY;
const MISTRAL_API_KEY = $env.MISTRAL_API_KEY;

const VALID_INTENTS = ['Appreciation', 'Product_Query', 'Catalogue', 'Professional', 'Post_Purchase'];

function normalizeIntent(rawText) {
  const cleaned = rawText.trim();
  if (VALID_INTENTS.includes(cleaned)) return cleaned;
  for (const intent of VALID_INTENTS) {
    if (cleaned.includes(intent)) return intent;
  }
  return 'Unknown';
}

async function callGeminiFamily(model, apiKey, text) {
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`;
  try {
    const data = await this.helpers.httpRequest({
      method: 'POST',
      url: url,
      headers: { 'Content-Type': 'application/json' },
      body: { contents: [{ parts: [{ text }] }] },
      json: true
    });
    const candidate = data?.candidates?.[0]?.content?.parts?.[0]?.text;
    if (!candidate) return { ok: false, reason: 'empty_candidates' };
    return { ok: true, text: candidate.trim() };
  } catch (err) {
    return { ok: false, reason: err.message };
  }
}

async function callGroq(apiKey, text) {
  try {
    const data = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.groq.com/openai/v1/chat/completions',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${apiKey}`
      },
      body: {
        model: 'llama-3.3-70b-versatile',
        messages: [{ role: 'user', content: text }]
      },
      json: true
    });
    const content = data?.choices?.[0]?.message?.content;
    if (!content) return { ok: false, reason: 'empty_choices' };
    return { ok: true, text: content.trim() };
  } catch (err) {
    return { ok: false, reason: err.message };
  }
}

async function callMistral(apiKey, text) {
  try {
    const data = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.mistral.ai/v1/chat/completions',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${apiKey}`
      },
      body: {
        model: 'mistral-small-latest',
        messages: [{ role: 'user', content: text }]
      },
      json: true
    });
    const content = data?.choices?.[0]?.message?.content;
    if (!content) return { ok: false, reason: 'empty_choices' };
    return { ok: true, text: content.trim() };
  } catch (err) {
    return { ok: false, reason: err.message };
  }
}

let result = await callGeminiFamily.call(this, 'gemini-3.1-flash-lite', GEMINI_API_KEY, fullPrompt);
let providerUsed = 'gemini';
const debugLog = [`gemini: ${result.ok ? 'OK' : result.reason}`];

if (!result.ok) {
  result = await callGeminiFamily.call(this, 'gemma-4-26b', GEMINI_API_KEY, fullPrompt);
  providerUsed = 'gemma';
  debugLog.push(`gemma: ${result.ok ? 'OK' : result.reason}`);
}

if (!result.ok) {
  result = await callGroq.call(this, GROQ_API_KEY, fullPrompt);
  providerUsed = 'groq';
  debugLog.push(`groq: ${result.ok ? 'OK' : result.reason}`);
}

if (!result.ok) {
  result = await callMistral.call(this, MISTRAL_API_KEY, fullPrompt);
  providerUsed = 'mistral';
  debugLog.push(`mistral: ${result.ok ? 'OK' : result.reason}`);
}

const finalIntent = result.ok ? normalizeIntent(result.text) : 'Unknown';

return {
  json: {
    intent: finalIntent,
    from_id: fromId,
    from_username: fromUsername,
    provider_used: result.ok ? providerUsed : 'none',
    debug: debugLog
  }
};

const staticData = $getWorkflowStaticData('global');
const now = new Date().toISOString();

// first run ever: default to 5 minutes ago so it doesn't try to fetch your entire history
const lastPollTimestamp = staticData.lastPollTimestamp || new Date(Date.now() - 5 * 60 * 1000).toISOString();

staticData.lastPollTimestamp = now; // update immediately, so next cycle starts from here

return [{ json: { lastPollTimestamp, currentPollTimestamp: now } }];

const lastPoll = new Date($('Get Last Poll Timestamp').first().json.lastPollTimestamp).getTime();
const conversations = $input.first().json.data || [];

const active = conversations.filter(c => {
  const updated = new Date(c.updated_time).getTime();
  return updated > lastPoll;
});

return active.map(c => ({ json: c }));

const MY_ACCOUNT_ID = 'YOUR_INSTAGRAM_BUSINESS_ACCOUNT_ID'; // akshaykala_ official account ID
const staticData = $getWorkflowStaticData('global');
const now = Date.now();
const LOCK_DURATION_MS = 20000;

if (staticData.lockedUntil && now < staticData.lockedUntil) {
  return [];
}
staticData.lockedUntil = now + LOCK_DURATION_MS;

const lastChecked = new Date(staticData.lastChecked || 0);

if (!staticData.processedMessageIds) {
  staticData.processedMessageIds = [];
}
if (!staticData.repliedMessageIds) {
  staticData.repliedMessageIds = [];
}

const processedIds = new Set(staticData.processedMessageIds);
const repliedIds = new Set(staticData.repliedMessageIds);

// Loop Over Items sends ONE conversation per execution now, not a bulk array
const items = $input.all();
let newMessages = [];
let latestTime = lastChecked;

for (const item of items) {
  const convo = item.json;
  const messages = convo.messages?.data || [];

  for (const msg of messages) {
    const msgTime = new Date(msg.created_time);
    const isNewByTime = msgTime > lastChecked;
    const isAlreadyProcessed = processedIds.has(msg.id);
    const isAlreadyReplied = repliedIds.has(msg.id);
    const isFromCustomer = msg.from.id !== MY_ACCOUNT_ID;

    if (isNewByTime && !isAlreadyProcessed && !isAlreadyReplied && isFromCustomer) {
      newMessages.push({
        conversation_id: convo.id,
        message_id: msg.id,
        text: msg.message,
        from_username: msg.from.username,
        from_id: msg.from.id,
        created_time: msg.created_time
      });
      processedIds.add(msg.id);
      if (msgTime > latestTime) {
        latestTime = msgTime;
      }
    } else if (isNewByTime && !isFromCustomer) {
      processedIds.add(msg.id);
    }
  }
}

staticData.lastChecked = latestTime.toISOString();
staticData.processedMessageIds = Array.from(processedIds).slice(-500);
staticData.repliedMessageIds = Array.from(repliedIds).slice(-500);

return newMessages.map(m => ({ json: m }));

